// jni_generator maps this to JNI_WallpaperHelper_OnColorsChanged().
// The _jni.h header declares it extern "C"; we define it here.
// ---------------------------------------------------------------------------
void JNI_WallpaperHelper_OnColorsChanged(
    JNIEnv* env,
    const base::android::JavaParamRef<jobject>& caller,
    jint primary_color,
    jint secondary_color,
    jint tertiary_color,
    jint color_hints) {
  auto* impl = reinterpret_cast<wallpaper::WallpaperManagerImpl*>(
      base::android::GetNativePointerFromJavaPeer(env, caller));
  if (impl)
    impl->OnWallpaperColorsChanged(env, primary_color, secondary_color,
                                   tertiary_color, color_hints);
}
